-- Current schema at version 32. Historical upgrades have their own frozen definitions.
CREATE TABLE actions (id INTEGER PRIMARY KEY,kind TEXT NOT NULL,params_json TEXT,plan_json TEXT,undo_json TEXT,status TEXT NOT NULL,created_at REAL,executed_at REAL);
CREATE TABLE album_artists (album_id INTEGER NOT NULL REFERENCES albums(id),position INTEGER NOT NULL CHECK(position>=0),artist_id INTEGER NOT NULL REFERENCES artists(id),credit TEXT NOT NULL,PRIMARY KEY(album_id,position));
CREATE TABLE album_discovery_memberships (album_id INTEGER PRIMARY KEY REFERENCES albums(id),found_at REAL,last_shown REAL,first_shown REAL,offered_count INTEGER NOT NULL DEFAULT 0,legacy_offered_count INTEGER NOT NULL DEFAULT 0,legacy_first_shown REAL,legacy_last_shown REAL);
CREATE TABLE album_fetch_state (album_id INTEGER PRIMARY KEY REFERENCES albums(id),fetched_at REAL,complete INTEGER NOT NULL CHECK(complete IN (0,1)),expected_track_count INTEGER NOT NULL CHECK(expected_track_count>=0));
CREATE TABLE album_library_legacy_cohort (identity_id INTEGER PRIMARY KEY REFERENCES identities(id),observed_at REAL);
CREATE TABLE album_library_memberships (id INTEGER PRIMARY KEY,album_id INTEGER NOT NULL REFERENCES albums(id),identity_id INTEGER REFERENCES identities(id),source TEXT NOT NULL,saved_at REAL,UNIQUE(album_id,identity_id));
CREATE TABLE album_library_revisions (identity_id INTEGER PRIMARY KEY REFERENCES identities(id),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0));
CREATE TABLE album_library_snapshots (identity_id INTEGER PRIMARY KEY REFERENCES identities(id),observed_at REAL NOT NULL);
CREATE TABLE album_provider_ids (provider TEXT NOT NULL,provider_id TEXT NOT NULL,album_id INTEGER NOT NULL REFERENCES albums(id),PRIMARY KEY(provider,provider_id),UNIQUE(album_id,provider));
CREATE TABLE album_share_snapshots (browse_id TEXT PRIMARY KEY,title TEXT NOT NULL,video_ids_json TEXT NOT NULL);
CREATE TABLE album_tracks (id INTEGER PRIMARY KEY,album_id INTEGER NOT NULL REFERENCES albums(id),entry_id INTEGER REFERENCES catalog_entries(id),recording_id INTEGER REFERENCES recordings(id),legacy_track_key TEXT,position INTEGER CHECK(position>=0),disc_number INTEGER CHECK(disc_number>0),track_number INTEGER CHECK(track_number>0),is_full INTEGER NOT NULL CHECK(is_full IN (0,1)),source TEXT NOT NULL,CHECK(entry_id IS NOT NULL OR recording_id IS NOT NULL OR legacy_track_key IS NOT NULL),CHECK(entry_id IS NULL OR recording_id IS NULL),UNIQUE(album_id,position));
CREATE TABLE albums (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,artist TEXT,year TEXT,type TEXT,thumbnail TEXT,genre TEXT,metadata_rank INTEGER NOT NULL,legacy_key TEXT UNIQUE);
CREATE TABLE artist_aliases (artist_id INTEGER NOT NULL REFERENCES artists(id),alias TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(artist_id,alias,source));
CREATE TABLE artist_credit_observations (id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),credit TEXT NOT NULL,credits_json TEXT NOT NULL,source TEXT NOT NULL,observed_at REAL);
CREATE TABLE artist_provider_ids (provider TEXT NOT NULL,provider_id TEXT NOT NULL,artist_id INTEGER NOT NULL REFERENCES artists(id),PRIMARY KEY(provider,provider_id));
CREATE TABLE artist_redirects (retired_id INTEGER PRIMARY KEY REFERENCES artists(id),artist_id INTEGER NOT NULL REFERENCES artists(id),source TEXT NOT NULL,created_at REAL NOT NULL,CHECK(retired_id<>artist_id));
CREATE TABLE artist_scans (artist TEXT PRIMARY KEY,scanned_at REAL,artist_id INTEGER REFERENCES artists(id));
CREATE TABLE artist_similarity_targets (source_artist_id INTEGER NOT NULL REFERENCES artists(id),target_artist_id INTEGER NOT NULL REFERENCES artists(id),weight REAL NOT NULL,PRIMARY KEY(source_artist_id,target_artist_id));
CREATE TABLE artists (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,provisional INTEGER NOT NULL CHECK(provisional IN (0,1)));
CREATE TABLE catalog_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT UNIQUE REFERENCES youtube_items(video_id),source_ref TEXT UNIQUE,CHECK((video_id IS NOT NULL)<>(source_ref IS NOT NULL)),FOREIGN KEY(video_id,recording_id) REFERENCES youtube_items(video_id,recording_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE catalog_field_hints (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL,source TEXT NOT NULL,value_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(entry_id,field,source));
CREATE TABLE cleanup_ignored (ytm TEXT NOT NULL REFERENCES playlist_scopes(ref),category TEXT NOT NULL,created_at REAL,PRIMARY KEY(ytm,category));
CREATE TABLE cluster_canvas (playlist_ytm TEXT PRIMARY KEY NOT NULL REFERENCES playlist_scopes(ref),state TEXT NOT NULL,created_at REAL);
CREATE TABLE discovered_artists (artist TEXT PRIMARY KEY,score REAL,because TEXT,fits TEXT,thumbnail TEXT,found_at REAL,last_shown REAL,genre TEXT,first_shown REAL,offered_count INTEGER NOT NULL DEFAULT 0,legacy_offered_count INTEGER NOT NULL DEFAULT 0,legacy_first_shown REAL,legacy_last_shown REAL,artist_id INTEGER REFERENCES artists(id));
CREATE TABLE discovery_artist_sources (artist_id INTEGER NOT NULL REFERENCES artists(id),source TEXT NOT NULL,identity_id INTEGER REFERENCES identities(id),score REAL NOT NULL,PRIMARY KEY(artist_id,source));
CREATE TABLE discovery_memberships (recording_id INTEGER PRIMARY KEY REFERENCES recordings(id),entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),found_at REAL,first_shown REAL,last_shown REAL,offered_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE discovery_sources (recording_id INTEGER NOT NULL REFERENCES recordings(id),source_token TEXT NOT NULL,input_video_id TEXT REFERENCES youtube_items(video_id),found_at REAL,source_type TEXT NOT NULL DEFAULT 'unknown',source_id TEXT,last_found_at REAL,PRIMARY KEY(recording_id,source_token));
CREATE TABLE discovery_visible_impressions (view_id TEXT NOT NULL,kind TEXT NOT NULL,item_id TEXT NOT NULL,shown_at REAL NOT NULL,PRIMARY KEY(view_id,kind,item_id));
CREATE TABLE enrichment_artwork (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),release_ids_json TEXT NOT NULL,status TEXT NOT NULL,failures INTEGER NOT NULL,retry_at REAL NOT NULL,error TEXT NOT NULL);
CREATE TABLE enrichment_conflict (id INTEGER PRIMARY KEY,track_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL,candidates TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0,resolved_value TEXT,updated_at REAL,recording_id INTEGER REFERENCES recordings(id),input_video_id TEXT REFERENCES youtube_items(video_id),field_scope TEXT NOT NULL DEFAULT 'legacy_item',UNIQUE(track_id,field));
CREATE TABLE enrichment_log (id INTEGER PRIMARY KEY,track_id INTEGER NOT NULL REFERENCES catalog_entries(id),run_id TEXT NOT NULL,provider TEXT NOT NULL,field TEXT NOT NULL,value TEXT,created_at REAL,recording_id INTEGER REFERENCES recordings(id),input_video_id TEXT REFERENCES youtube_items(video_id),field_scope TEXT NOT NULL DEFAULT 'legacy_item');
CREATE TABLE enrichment_provider_config (provider TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE enrichment_provider_cooldowns (provider TEXT PRIMARY KEY,failures INTEGER NOT NULL,retry_at REAL NOT NULL,error TEXT NOT NULL);
CREATE TABLE enrichment_provider_jobs (recording_id INTEGER NOT NULL REFERENCES recordings(id),provider TEXT NOT NULL,PRIMARY KEY(recording_id,provider));
CREATE TABLE enrichment_provider_state (recording_id INTEGER NOT NULL REFERENCES recordings(id),provider TEXT NOT NULL,cycle REAL NOT NULL,at REAL NOT NULL,status TEXT NOT NULL,fields_json TEXT NOT NULL,failures INTEGER NOT NULL,retry_at REAL NOT NULL,error TEXT NOT NULL,PRIMARY KEY(recording_id,provider));
CREATE TABLE entry_field_choices (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL,value_json TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(entry_id,field));
CREATE TABLE genre_alias (label_key TEXT PRIMARY KEY,label TEXT NOT NULL,genre_key TEXT NOT NULL REFERENCES genre_catalog(key),source TEXT NOT NULL);
CREATE TABLE genre_catalog (key TEXT PRIMARY KEY,name TEXT NOT NULL,family_key TEXT REFERENCES genre_family(key),source TEXT NOT NULL,family_source TEXT,description TEXT NOT NULL DEFAULT '');
CREATE TABLE genre_external_id (provider TEXT NOT NULL,external_id TEXT NOT NULL,genre_key TEXT NOT NULL REFERENCES genre_catalog(key),PRIMARY KEY(provider,external_id));
CREATE TABLE genre_family (key TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE genre_whitelist (name TEXT PRIMARY KEY COLLATE NOCASE);
CREATE TABLE hidden_playlists (ytm TEXT PRIMARY KEY NOT NULL REFERENCES playlist_scopes(ref));
CREATE TABLE history_items (snapshot_id INTEGER NOT NULL REFERENCES history_snapshots(id),identity_key TEXT NOT NULL,recording_id INTEGER REFERENCES recordings(id),raw_identity_key TEXT,source TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE history_snapshots (id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES identities(id),taken_at REAL NOT NULL);
CREATE TABLE home_hidden_facet (axis TEXT PRIMARY KEY);
CREATE TABLE identities (id INTEGER PRIMARY KEY,label TEXT NOT NULL,credential_ref TEXT NOT NULL,brand_account_id TEXT,is_master INTEGER NOT NULL DEFAULT 0,last_auth_ok REAL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(label));
CREATE TABLE identity_state_archive (kind TEXT NOT NULL,source_id TEXT NOT NULL,payload TEXT NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(kind,source_id));
CREATE TABLE ignored_merge_members (signature TEXT NOT NULL REFERENCES ignored_merges(signature) ON DELETE CASCADE,playlist_ref TEXT NOT NULL REFERENCES playlist_scopes(ref),PRIMARY KEY(signature,playlist_ref));
CREATE TABLE ignored_merges (signature TEXT PRIMARY KEY NOT NULL,members TEXT NOT NULL,created_at REAL);
CREATE TABLE item_field_sources (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL,source TEXT NOT NULL,selected_at REAL,PRIMARY KEY(entry_id,field));
CREATE TABLE item_ratings (identity_id INTEGER NOT NULL REFERENCES identities(id),video_id TEXT NOT NULL,status TEXT NOT NULL,source TEXT NOT NULL,observed_at REAL NOT NULL,PRIMARY KEY(identity_id,video_id));
CREATE TABLE item_recording_associations (id INTEGER PRIMARY KEY,video_id TEXT NOT NULL REFERENCES youtube_items(video_id),recording_id INTEGER NOT NULL REFERENCES recordings(id),previous_recording_id INTEGER REFERENCES recordings(id),source TEXT NOT NULL,evidence TEXT NOT NULL,at REAL);
CREATE TABLE legacy_enrichment_attempts (identity_key TEXT PRIMARY KEY,payload TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE legacy_track_evidence (kind TEXT NOT NULL,source_id TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,source_id));
CREATE TABLE legacy_track_refs (legacy_id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT REFERENCES youtube_items(video_id));
CREATE TABLE library_memberships (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),origin TEXT NOT NULL,added_at REAL);
CREATE TABLE listening_calendars (identity_id INTEGER PRIMARY KEY REFERENCES identities(id),timezone TEXT NOT NULL,confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1)));
CREATE TABLE listening_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,identity_id INTEGER NOT NULL REFERENCES identities(id),raw_identity_key TEXT NOT NULL,identity_key TEXT NOT NULL,recording_id INTEGER REFERENCES recordings(id),source_day TEXT NOT NULL CHECK(date(source_day) IS NOT NULL AND date(source_day)=source_day),day TEXT CHECK(day IS NULL OR (date(day) IS NOT NULL AND date(day)=day)),source TEXT NOT NULL,timezone TEXT NOT NULL,precision TEXT NOT NULL CHECK(precision='calendar_day'),first_observed_at REAL NOT NULL,last_observed_at REAL NOT NULL,UNIQUE(identity_id,raw_identity_key,source_day,source,timezone));
CREATE TABLE metadata_decisions (id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),field TEXT NOT NULL,value_json TEXT NOT NULL,source TEXT NOT NULL,chosen_at REAL,legacy_ref TEXT UNIQUE);
CREATE TABLE metadata_findings (id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),field TEXT NOT NULL,provider TEXT NOT NULL,value_json TEXT NOT NULL,observed_at REAL NOT NULL);
CREATE TABLE overlap_ignored (ytm TEXT PRIMARY KEY NOT NULL REFERENCES playlist_scopes(ref),created_at REAL);
CREATE TABLE overlap_kept (a TEXT NOT NULL REFERENCES playlist_scopes(ref),b TEXT NOT NULL REFERENCES playlist_scopes(ref),created_at REAL,PRIMARY KEY(a,b));
CREATE TABLE play_event_calendar (event_id INTEGER PRIMARY KEY REFERENCES play_events(id) ON DELETE CASCADE,day TEXT NOT NULL CHECK(date(day) IS NOT NULL AND date(day)=day),timezone TEXT NOT NULL);
CREATE TABLE play_event_sources (event_id INTEGER NOT NULL REFERENCES play_events(id) ON DELETE CASCADE,source TEXT NOT NULL,PRIMARY KEY(event_id,source));
CREATE TABLE play_events (id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES identities(id),identity_key TEXT NOT NULL,video_id TEXT,played_at REAL NOT NULL,playlist_ytm_id TEXT,like_status TEXT,is_generated INTEGER CHECK(is_generated IN (0,1)),source TEXT NOT NULL DEFAULT '',recording_id INTEGER REFERENCES recordings(id),raw_identity_key TEXT);
CREATE TABLE player_events (id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES identities(id),kind TEXT NOT NULL,video_id TEXT,position REAL,duration REAL,playlist_ytm_id TEXT,payload TEXT,at REAL NOT NULL);
CREATE TABLE playlist_group (ytm TEXT PRIMARY KEY NOT NULL REFERENCES playlist_scopes(ref),name TEXT NOT NULL);
CREATE TABLE playlist_items (playlist_id INTEGER NOT NULL REFERENCES playlists(id),video_id TEXT NOT NULL REFERENCES youtube_items(video_id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,video_id));
CREATE TABLE playlist_membership_refs (id INTEGER PRIMARY KEY AUTOINCREMENT,scope_ref TEXT REFERENCES playlist_scopes(ref),identity_id INTEGER REFERENCES identities(id),CHECK((scope_ref IS NULL)=(identity_id IS NULL)));
CREATE TABLE playlist_provenance (ytm TEXT PRIMARY KEY NOT NULL REFERENCES playlist_scopes(ref),origin TEXT NOT NULL CHECK(origin IN ('tuneconsole','ordinary')),adopted INTEGER NOT NULL CHECK(adopted IN (0,1)),description TEXT);
CREATE TABLE playlist_scopes (ref TEXT PRIMARY KEY NOT NULL,provider_id TEXT NOT NULL,identity_id INTEGER REFERENCES identities(id),kind TEXT NOT NULL CHECK(kind IN ('shared','account','legacy')),CHECK((kind='account' AND identity_id IS NOT NULL) OR (kind<>'account' AND identity_id IS NULL)),UNIQUE(provider_id,identity_id));
CREATE TABLE playlists (id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES identities(id),ytm_playlist_id TEXT NOT NULL,title TEXT,track_count INTEGER,content_hash TEXT,first_seen REAL,last_seen REAL,last_changed REAL,created_at REAL,created_at_source TEXT,thumbnail TEXT,scope_ref TEXT REFERENCES playlist_scopes(ref),UNIQUE(identity_id,ytm_playlist_id));
CREATE TABLE provider_attempts (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),input_video_id TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL,at REAL,status TEXT NOT NULL,fields_json TEXT NOT NULL);
CREATE TABLE rec_artist_content_vectors (artist TEXT PRIMARY KEY,vec BLOB NOT NULL);
CREATE TABLE rec_artist_similar (artist TEXT PRIMARY KEY,payload TEXT NOT NULL,fetched_at REAL,artist_id INTEGER REFERENCES artists(id));
CREATE TABLE rec_artist_vectors (artist TEXT PRIMARY KEY,vec BLOB NOT NULL);
CREATE TABLE rec_content_vectors (identity_key TEXT PRIMARY KEY,vec BLOB NOT NULL);
CREATE TABLE rec_discovered_content_vectors (identity_key TEXT PRIMARY KEY,vec BLOB NOT NULL);
CREATE TABLE rec_feedback (surface TEXT NOT NULL,item_key TEXT NOT NULL,kind TEXT NOT NULL,reason TEXT,scope TEXT NOT NULL DEFAULT '',until REAL,created_at REAL,target_type TEXT NOT NULL DEFAULT 'legacy_unresolved',recording_id INTEGER REFERENCES recordings(id),artist_id INTEGER REFERENCES artists(id),PRIMARY KEY(surface,item_key,scope));
CREATE TABLE rec_grad_log (id INTEGER PRIMARY KEY AUTOINCREMENT,axis TEXT NOT NULL,source TEXT NOT NULL,score REAL NOT NULL,factor REAL NOT NULL,new_weight REAL NOT NULL,created_at REAL NOT NULL);
CREATE TABLE rec_impressions (surface TEXT NOT NULL,item_key TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,last_shown REAL,PRIMARY KEY(surface,item_key));
CREATE TABLE rec_lane_impressions (id INTEGER PRIMARY KEY,lane TEXT NOT NULL,identity_key TEXT NOT NULL,at REAL NOT NULL,recording_id INTEGER REFERENCES recordings(id),raw_identity_key TEXT);
CREATE TABLE rec_lean (axis TEXT PRIMARY KEY,value REAL NOT NULL DEFAULT 1.0,updated_at REAL,last_graduated_day TEXT);
CREATE TABLE rec_mode_impressions (epoch INTEGER NOT NULL,lane TEXT NOT NULL,mode_id INTEGER REFERENCES taste_modes(mode_id),ranker TEXT,created_at REAL NOT NULL,legacy_mode_id INTEGER,CHECK((mode_id IS NOT NULL)<>(legacy_mode_id IS NOT NULL)),PRIMARY KEY(epoch,lane));
CREATE TABLE rec_mode_picks (playlist_id INTEGER PRIMARY KEY NOT NULL REFERENCES playlist_membership_refs(id),mode_id INTEGER REFERENCES taste_modes(mode_id),ranker TEXT,created_at REAL NOT NULL,legacy_mode_id INTEGER,CHECK((mode_id IS NOT NULL)<>(legacy_mode_id IS NOT NULL)));
CREATE TABLE rec_model_forecasts (run_id INTEGER NOT NULL REFERENCES rec_model_selection_runs(id),made_at REAL NOT NULL,forecast_json TEXT NOT NULL,PRIMARY KEY(run_id,made_at));
CREATE TABLE rec_model_previous_vectors (run_id INTEGER NOT NULL REFERENCES rec_model_selection_runs(id),identity_key TEXT NOT NULL,vec BLOB NOT NULL,PRIMARY KEY(run_id,identity_key));
CREATE TABLE rec_model_selection_runs (id INTEGER PRIMARY KEY,started_at REAL NOT NULL,result_json TEXT NOT NULL,identity_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rec_mood (created_at REAL NOT NULL,direction INTEGER NOT NULL,keys TEXT NOT NULL);
CREATE TABLE rec_play_grad (axis TEXT PRIMARY KEY,last_graduated_day TEXT);
CREATE TABLE rec_proposals (surface TEXT PRIMARY KEY,payload TEXT NOT NULL,built_at REAL);
CREATE TABLE rec_recipes (playlist_ytm TEXT PRIMARY KEY NOT NULL REFERENCES playlist_scopes(ref),recipe TEXT NOT NULL,created_at REAL);
CREATE TABLE rec_response_events (id INTEGER PRIMARY KEY,event_id TEXT NOT NULL,kind TEXT NOT NULL,identity_key TEXT NOT NULL,at REAL NOT NULL,is_generated INTEGER NOT NULL DEFAULT 0,UNIQUE(event_id,kind,identity_key));
CREATE TABLE rec_served_impressions (id INTEGER PRIMARY KEY,request_id TEXT NOT NULL,surface TEXT NOT NULL,lane TEXT NOT NULL,mode_id INTEGER,identity_key TEXT NOT NULL,rank INTEGER NOT NULL,score REAL,model_version TEXT NOT NULL,provenance TEXT NOT NULL,served_at REAL NOT NULL,recording_id INTEGER REFERENCES recordings(id),raw_identity_key TEXT,UNIQUE(request_id,surface,rank));
CREATE TABLE rec_serving_policies (model_version TEXT PRIMARY KEY,configuration TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE rec_theme (facet TEXT PRIMARY KEY,score REAL NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE rec_vectors (identity_key TEXT PRIMARY KEY,vec BLOB NOT NULL);
CREATE TABLE rec_weights (axis TEXT PRIMARY KEY,weight REAL NOT NULL DEFAULT 1.0,updated_at REAL);
CREATE TABLE recording_aliases (alias TEXT NOT NULL,recording_id INTEGER NOT NULL REFERENCES recordings(id),source TEXT NOT NULL,PRIMARY KEY(alias,recording_id));
CREATE TABLE recording_field_sources (recording_id INTEGER NOT NULL REFERENCES recordings(id),field TEXT NOT NULL,source TEXT NOT NULL,selected_at REAL,PRIMARY KEY(recording_id,field));
CREATE TABLE recording_identifiers (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),scheme TEXT NOT NULL,entity_type TEXT NOT NULL,value TEXT NOT NULL,source TEXT NOT NULL,input_video_id TEXT REFERENCES youtube_items(video_id),status TEXT NOT NULL CHECK(status IN ('candidate','accepted','conflicting')),observed_at REAL);
CREATE TABLE recording_redirects (retired_id INTEGER PRIMARY KEY REFERENCES recordings(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),source TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE TABLE recordings (id INTEGER PRIMARY KEY AUTOINCREMENT,identity_key TEXT NOT NULL UNIQUE,title TEXT,artist TEXT,provisional INTEGER NOT NULL DEFAULT 1,genre TEXT,bpm REAL,energy REAL,danceability REAL,mb_recording_id TEXT,music_key TEXT,music_scale TEXT,mood_happy REAL,mood_sad REAL,mood_relaxed REAL,mood_acoustic REAL,instrumental REAL,created_at REAL,first_enriched_at REAL,last_enriched_at REAL);
CREATE TABLE road_trip_drafts (recipe_id INTEGER PRIMARY KEY REFERENCES road_trip_recipes(id) ON DELETE CASCADE,state TEXT NOT NULL,updated_at REAL NOT NULL);
CREATE TABLE road_trip_recipes (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,own_pct INTEGER NOT NULL,artists TEXT NOT NULL,genres TEXT NOT NULL,blacklist_genres TEXT NOT NULL,target_minutes INTEGER NOT NULL,last_playlist_id TEXT,created_at REAL NOT NULL,updated_at REAL NOT NULL,familiarity_pct INTEGER NOT NULL DEFAULT 50);
CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY,name TEXT NOT NULL,applied_at REAL NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE spotify_history_listens (identity_id INTEGER NOT NULL REFERENCES identities(id),track_uri TEXT NOT NULL,ended_at REAL NOT NULL,event_id INTEGER REFERENCES play_events(id) ON DELETE SET NULL,artist_id INTEGER REFERENCES artists(id),PRIMARY KEY(identity_id,track_uri,ended_at));
CREATE TABLE suppressed_overlaps (a TEXT NOT NULL REFERENCES playlist_scopes(ref),b TEXT NOT NULL REFERENCES playlist_scopes(ref),created_at REAL,PRIMARY KEY(a,b));
CREATE TABLE takeout_imports (id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES identities(id),fingerprint TEXT NOT NULL,imported_at REAL NOT NULL,observed_start REAL,observed_end REAL,unparsed_dates INTEGER NOT NULL CHECK(unparsed_dates>=0),account_verified INTEGER NOT NULL DEFAULT 0 CHECK(account_verified IN (0,1)),complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN (0,1)),coverage_start REAL,coverage_end REAL,CHECK(coverage_start IS NULL OR coverage_end>coverage_start));
CREATE TABLE taste_modes (mode_id INTEGER PRIMARY KEY,label TEXT NOT NULL,families TEXT NOT NULL,centroid BLOB NOT NULL,size INTEGER NOT NULL,rep_keys TEXT NOT NULL,active INTEGER NOT NULL,first_seen REAL NOT NULL,last_seen REAL NOT NULL,space TEXT NOT NULL DEFAULT '');
CREATE TABLE track_artists (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),position INTEGER NOT NULL CHECK(position>=0),artist_id INTEGER NOT NULL REFERENCES artists(id),credit TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(entry_id,position));
CREATE TABLE trend_first_play (kind TEXT NOT NULL,id_key TEXT NOT NULL,first_day INTEGER NOT NULL,first_ts REAL NOT NULL,source TEXT NOT NULL,PRIMARY KEY(kind,id_key));
CREATE TABLE unresolved_items (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),title TEXT,artist TEXT,orig_title TEXT,orig_artist TEXT,album TEXT,duration_s INTEGER,available INTEGER,video_type TEXT,artist_browse_id TEXT,album_browse_id TEXT,thumbnail TEXT,mb_year TEXT,loudness REAL,dynamic_complexity REAL,popularity INTEGER,gain REAL,label TEXT);
CREATE TABLE unresolved_playlist_items (playlist_id INTEGER NOT NULL REFERENCES playlists(id),entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,entry_id));
CREATE TABLE wiki_cards (subject TEXT PRIMARY KEY,kind TEXT NOT NULL,display TEXT NOT NULL,title TEXT,extract TEXT,thumbnail TEXT,url TEXT,found INTEGER NOT NULL,fetched_at REAL NOT NULL);
CREATE TABLE youtube_items (video_id TEXT PRIMARY KEY NOT NULL CHECK(length(trim(video_id))>0),recording_id INTEGER NOT NULL REFERENCES recordings(id),title TEXT,artist TEXT,orig_title TEXT,orig_artist TEXT,album TEXT,duration_s INTEGER,available INTEGER,video_type TEXT,artist_browse_id TEXT,album_browse_id TEXT,thumbnail TEXT,mb_year TEXT,loudness REAL,dynamic_complexity REAL,popularity INTEGER,gain REAL,label TEXT,UNIQUE(video_id,recording_id));
CREATE INDEX discovery_artist_sources_identity ON discovery_artist_sources(identity_id,source);
CREATE INDEX idx_enrichment_log_track ON enrichment_log(track_id);
CREATE INDEX idx_genre_alias_genre ON genre_alias(genre_key);
CREATE INDEX ix_album_artist ON album_artists(artist_id,album_id);
CREATE UNIQUE INDEX ix_album_library_unknown ON album_library_memberships(album_id) WHERE identity_id IS NULL;
CREATE INDEX ix_album_track_entry ON album_tracks(entry_id,album_id);
CREATE UNIQUE INDEX ix_album_track_incidental ON album_tracks(album_id,entry_id) WHERE is_full=0;
CREATE INDEX ix_album_track_recording ON album_tracks(recording_id,album_id);
CREATE INDEX ix_artist_alias ON artist_aliases(alias,artist_id);
CREATE INDEX ix_artist_provider_subject ON artist_provider_ids(artist_id);
CREATE INDEX ix_artist_provisional_name ON artists(name) WHERE provisional=1;
CREATE INDEX ix_artist_redirect_target ON artist_redirects(artist_id);
CREATE UNIQUE INDEX ix_artist_scans_artist ON artist_scans(artist_id);
CREATE UNIQUE INDEX ix_discovered_artists_artist ON discovered_artists(artist_id);
CREATE INDEX ix_entries_recording ON catalog_entries(recording_id);
CREATE INDEX ix_history_item_key_snapshot ON history_items(identity_key,snapshot_id);
CREATE INDEX ix_history_item_recording_snapshot ON history_items(recording_id,snapshot_id);
CREATE INDEX ix_history_snapshot_account_time ON history_snapshots(identity_id,taken_at);
CREATE INDEX ix_lane_impressions_at ON rec_lane_impressions(at);
CREATE INDEX ix_listening_observation_account_day ON listening_observations(identity_id,day);
CREATE INDEX ix_listening_observation_subject_day ON listening_observations(identity_key,day,identity_id);
CREATE INDEX ix_metadata_decisions_entry ON metadata_decisions(entry_id,field,chosen_at);
CREATE INDEX ix_metadata_findings_subject ON metadata_findings(recording_id,field,provider,observed_at);
CREATE INDEX ix_mode_pick_mode_time ON rec_mode_picks(mode_id,created_at);
CREATE INDEX ix_play_event_account_key_time ON play_events(identity_id,identity_key,played_at);
CREATE INDEX ix_play_event_account_playlist_time ON play_events(identity_id,playlist_ytm_id,played_at);
CREATE INDEX ix_play_event_account_time ON play_events(identity_id,played_at DESC,id DESC);
CREATE INDEX ix_play_event_calendar_day ON play_event_calendar(day,event_id);
CREATE INDEX ix_play_event_recording_time ON play_events(recording_id,played_at);
CREATE INDEX ix_play_event_source ON play_event_sources(source,event_id);
CREATE INDEX ix_play_events_key ON play_events(identity_key);
CREATE INDEX ix_play_events_time ON play_events(played_at);
CREATE INDEX ix_player_event_account_playlist_time ON player_events(identity_id,playlist_ytm_id,at);
CREATE INDEX ix_player_events_at ON player_events(at);
CREATE INDEX ix_player_events_kind_at ON player_events(kind, at);
CREATE UNIQUE INDEX ix_playlist_item_position ON playlist_items(playlist_id,position);
CREATE INDEX ix_playlist_item_video ON playlist_items(video_id);
CREATE INDEX ix_playlist_scope ON playlists(scope_ref,identity_id);
CREATE UNIQUE INDEX ix_playlist_shared ON playlist_scopes(provider_id,kind) WHERE identity_id IS NULL;
CREATE INDEX ix_provider_attempt_subject ON provider_attempts(recording_id,input_video_id,provider,at);
CREATE UNIQUE INDEX ix_rec_artist_similar_artist ON rec_artist_similar(artist_id);
CREATE INDEX ix_rec_feedback_artist ON rec_feedback(artist_id,kind);
CREATE INDEX ix_rec_response_at ON rec_response_events(at);
CREATE INDEX ix_rec_served_at ON rec_served_impressions(served_at);
CREATE INDEX ix_rec_served_key_at ON rec_served_impressions(identity_key, served_at);
CREATE INDEX ix_recording_identifier ON recording_identifiers(scheme,entity_type,value);
CREATE INDEX ix_track_artist_subject ON track_artists(artist_id,entry_id);
CREATE INDEX ix_unresolved_playlist_entry ON unresolved_playlist_items(entry_id,playlist_id);
CREATE UNIQUE INDEX ix_unresolved_playlist_position ON unresolved_playlist_items(playlist_id,position);
CREATE INDEX ix_youtube_recording ON youtube_items(recording_id);
CREATE VIEW album_track_links AS SELECT MIN(t.id) id,p.provider_id browse_id,e.recording_id,t.entry_id,e.video_id,MIN(t.source) source FROM album_tracks t JOIN album_provider_ids p ON p.album_id=t.album_id AND p.provider='youtube' JOIN catalog_entries e ON e.id=t.entry_id GROUP BY t.album_id,t.entry_id;
CREATE VIEW album_tracklists AS SELECT p.provider_id browse_id,a.title,a.artist,a.thumbnail,(SELECT json_group_array(k) FROM (SELECT COALESCE(r.identity_key,t.legacy_track_key) k FROM album_tracks t LEFT JOIN catalog_entries e ON e.id=t.entry_id LEFT JOIN recordings r ON r.id=COALESCE(e.recording_id,t.recording_id) WHERE t.album_id=a.id AND t.is_full=1 ORDER BY t.position IS NULL,t.position,t.id)) track_keys FROM album_fetch_state f JOIN albums a ON a.id=f.album_id JOIN album_provider_ids p ON p.album_id=a.id AND p.provider='youtube' WHERE f.complete=1;
CREATE VIEW catalog_enrichment_tracks AS SELECT c.*,r.id queue_order,CASE WHEN EXISTS(SELECT 1 FROM library_memberships lm JOIN catalog_entries e ON e.id=lm.entry_id WHERE e.recording_id=r.id) THEN 'library' ELSE 'discovery' END source FROM recordings r JOIN catalog_tracks c ON c.id=COALESCE((SELECT MIN(e.id) FROM catalog_entries e JOIN library_memberships lm ON lm.entry_id=e.id WHERE e.recording_id=r.id),(SELECT entry_id FROM discovery_memberships WHERE recording_id=r.id));
CREATE VIEW catalog_tracks AS SELECT e.id,e.recording_id,e.video_id,r.identity_key,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='title') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='title') ELSE COALESCE(y.title,u.title) END AS title,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist') ELSE COALESCE(y.artist,u.artist) END AS artist,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_title') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_title') ELSE COALESCE(y.orig_title,u.orig_title) END AS orig_title,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_artist') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_artist') ELSE COALESCE(y.orig_artist,u.orig_artist) END AS orig_artist,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album') ELSE COALESCE(y.album,u.album) END AS album,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='duration_s') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='duration_s') ELSE COALESCE(y.duration_s,u.duration_s) END AS duration_s,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='available') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='available') ELSE CASE WHEN e.video_id IS NULL THEN 0 ELSE COALESCE(y.available,u.available) END END AS available,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='video_type') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='video_type') ELSE COALESCE(y.video_type,u.video_type) END AS video_type,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist_browse_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist_browse_id') ELSE COALESCE(y.artist_browse_id,u.artist_browse_id) END AS artist_browse_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album_browse_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album_browse_id') ELSE COALESCE(y.album_browse_id,u.album_browse_id) END AS album_browse_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='thumbnail') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='thumbnail') ELSE COALESCE(y.thumbnail,u.thumbnail) END AS thumbnail,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_year') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_year') ELSE COALESCE(y.mb_year,u.mb_year) END AS mb_year,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='loudness') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='loudness') ELSE COALESCE(y.loudness,u.loudness) END AS loudness,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='dynamic_complexity') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='dynamic_complexity') ELSE COALESCE(y.dynamic_complexity,u.dynamic_complexity) END AS dynamic_complexity,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='popularity') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='popularity') ELSE COALESCE(y.popularity,u.popularity) END AS popularity,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='gain') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='gain') ELSE COALESCE(y.gain,u.gain) END AS gain,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='label') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='label') ELSE COALESCE(y.label,u.label) END AS label,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='genre') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='genre') ELSE r.genre END AS genre,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='bpm') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='bpm') ELSE r.bpm END AS bpm,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='energy') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='energy') ELSE r.energy END AS energy,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='danceability') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='danceability') ELSE r.danceability END AS danceability,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_recording_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_recording_id') ELSE r.mb_recording_id END AS mb_recording_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_key') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_key') ELSE r.music_key END AS music_key,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_scale') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_scale') ELSE r.music_scale END AS music_scale,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_happy') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_happy') ELSE r.mood_happy END AS mood_happy,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_sad') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_sad') ELSE r.mood_sad END AS mood_sad,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_relaxed') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_relaxed') ELSE r.mood_relaxed END AS mood_relaxed,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_acoustic') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_acoustic') ELSE r.mood_acoustic END AS mood_acoustic,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='instrumental') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='instrumental') ELSE r.instrumental END AS instrumental,r.created_at,r.first_enriched_at,r.last_enriched_at FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id LEFT JOIN youtube_items y ON y.video_id=e.video_id LEFT JOIN unresolved_items u ON u.entry_id=e.id;
CREATE VIEW discovered_albums AS SELECT p.provider_id browse_id,a.artist,a.title,a.year,a.thumbnail,m.found_at,m.last_shown,a.genre,m.first_shown,m.offered_count,m.legacy_offered_count,m.legacy_first_shown,m.legacy_last_shown,(SELECT artist_id FROM album_artists aa WHERE aa.album_id=a.id ORDER BY position LIMIT 1) artist_id FROM album_discovery_memberships m JOIN albums a ON a.id=m.album_id JOIN album_provider_ids p ON p.album_id=a.id AND p.provider='youtube';
CREATE VIEW discovered_tracks AS SELECT c.*,c.mb_year year,d.found_at,d.first_shown,d.last_shown,d.offered_count,c.last_enriched_at last_enriched,(SELECT source_token FROM discovery_sources s WHERE s.recording_id=d.recording_id ORDER BY s.found_at,source_token LIMIT 1) source_browse_id FROM discovery_memberships d JOIN catalog_tracks c ON c.id=d.entry_id;
CREATE VIEW eligible_listening_evidence AS
SELECT e.* FROM listening_evidence e
WHERE (e.event_id IS NOT NULL AND e.is_generated=0)
   OR (e.event_id IS NULL AND (e.source<>'ytm_history' OR NOT EXISTS (
       SELECT 1 FROM listening_evidence g WHERE g.event_id IS NOT NULL
       AND g.is_generated=1 AND g.identity_id=e.identity_id
       AND g.identity_key=e.identity_key AND g.day=e.day)
       OR EXISTS (SELECT 1 FROM listening_evidence organic
           WHERE organic.identity_id=e.identity_id AND organic.identity_key=e.identity_key
           AND organic.day=e.day AND organic.is_generated=0
           AND (organic.event_id IS NOT NULL OR organic.source<>'ytm_history'))));
CREATE VIEW legacy_listening_observations AS
SELECT 'legacy:'||hi.rowid evidence_id,hs.identity_id,hi.identity_key,hi.recording_id,
       date(hs.taken_at,'unixepoch') day,hi.source,NULL timezone,
       'legacy_unknown' precision,hs.taken_at observed_at
FROM history_items hi JOIN history_snapshots hs ON hs.id=hi.snapshot_id;
CREATE VIEW listening_activity AS
SELECT pe.identity_id,pe.identity_key,pe.recording_id,c.day,pe.played_at at,
       'exact_timestamp' precision,pe.id event_id
FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
WHERE COALESCE(pe.is_generated,0)=0
UNION ALL
SELECT d.identity_id,d.identity_key,d.recording_id,d.day,d.day_ts,
       'calendar_day',NULL FROM listening_days d
WHERE NOT EXISTS (SELECT 1 FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
    WHERE pe.identity_id=d.identity_id AND pe.identity_key=d.identity_key AND c.day=d.day
    AND COALESCE(pe.is_generated,0)=0);
CREATE VIEW listening_daily_items AS
SELECT identity_id||':'||day||':'||identity_key rowid,identity_id||':'||day snapshot_id,
       identity_key,recording_id,source,day,identity_id,last_event_at,last_observed_at
FROM listening_days;
CREATE VIEW listening_daily_snapshots AS
SELECT identity_id||':'||day id,identity_id,day_ts taken_at,day
FROM listening_days GROUP BY identity_id,day;
CREATE VIEW listening_days AS
SELECT identity_id,identity_key,MIN(recording_id) recording_id,day,
       CAST(strftime('%s',day||' 12:00:00') AS REAL) day_ts,
       MAX(CASE WHEN event_id IS NOT NULL THEN observed_at END) last_event_at,
       MAX(observed_at) last_observed_at,
       CASE WHEN MIN(source)=MAX(source) THEN MIN(source) ELSE 'multiple' END source
FROM eligible_listening_evidence GROUP BY identity_id,identity_key,day;
CREATE VIEW listening_evidence AS
SELECT 'day:'||id evidence_id,identity_id,identity_key,recording_id,day,source,timezone,
       precision,last_observed_at observed_at,NULL event_id,0 is_generated
FROM listening_observations WHERE day IS NOT NULL
UNION ALL
SELECT evidence_id,identity_id,identity_key,recording_id,day,source,timezone,precision,
       observed_at,NULL,0 FROM legacy_listening_observations
UNION ALL
SELECT 'event:'||pe.id||':'||s.source,pe.identity_id,pe.identity_key,pe.recording_id,c.day,
       s.source,c.timezone,'exact_timestamp',pe.played_at,pe.id,COALESCE(pe.is_generated,0)
FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
JOIN play_event_sources s ON s.event_id=pe.id;
CREATE VIEW playable_library_tracks AS SELECT t.* FROM tracks t JOIN (SELECT e.recording_id,MIN(e.id) entry_id FROM catalog_entries e JOIN library_memberships m ON m.entry_id=e.id JOIN youtube_items y ON y.video_id=e.video_id WHERE COALESCE(y.available,1)<>0 GROUP BY e.recording_id) playable ON playable.entry_id=t.id;
CREATE VIEW playlist_tracks AS SELECT p.playlist_id,e.id track_id,p.position FROM playlist_items p JOIN catalog_entries e ON e.video_id=p.video_id UNION ALL SELECT playlist_id,entry_id,position FROM unresolved_playlist_items;
CREATE VIEW quarantined_playlists AS SELECT ytm,'Generated' name FROM playlist_provenance WHERE origin='tuneconsole' AND adopted=0;
CREATE VIEW saved_albums AS SELECT p.provider_id browse_id,a.title,a.artist,a.year,a.type,a.thumbnail FROM albums a JOIN album_provider_ids p ON p.album_id=a.id AND p.provider='youtube' WHERE EXISTS(SELECT 1 FROM album_library_memberships m WHERE m.album_id=a.id);
CREATE VIEW tracks AS SELECT c.* FROM catalog_tracks c JOIN library_memberships m ON m.entry_id=c.id;
CREATE TRIGGER album_track_links_delete INSTEAD OF DELETE ON album_track_links BEGIN DELETE FROM album_tracks WHERE album_id=(SELECT album_id FROM album_provider_ids WHERE provider='youtube' AND provider_id=OLD.browse_id) AND entry_id=OLD.entry_id; END;
CREATE TRIGGER artist_redirect_insert BEFORE INSERT ON artist_redirects WHEN EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) OR NOT EXISTS(SELECT 1 FROM artists WHERE id=NEW.retired_id AND provisional=1) OR EXISTS(SELECT 1 FROM artist_provider_ids WHERE artist_id=NEW.retired_id) OR NOT EXISTS(SELECT 1 FROM artists a JOIN artist_provider_ids p ON p.artist_id=a.id WHERE a.id=NEW.artist_id AND a.provisional=0) BEGIN SELECT RAISE(ABORT,'Artist redirect requires a provisional source and canonical target'); END;
CREATE TRIGGER artist_redirect_update BEFORE UPDATE ON artist_redirects WHEN NEW.retired_id<>OLD.retired_id OR EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) OR NOT EXISTS(SELECT 1 FROM artists WHERE id=NEW.retired_id AND provisional=1) OR EXISTS(SELECT 1 FROM artist_provider_ids WHERE artist_id=NEW.retired_id) OR NOT EXISTS(SELECT 1 FROM artists a JOIN artist_provider_ids p ON p.artist_id=a.id WHERE a.id=NEW.artist_id AND a.provisional=0) BEGIN SELECT RAISE(ABORT,'Artist redirect requires a provisional source and canonical target'); END;
CREATE TRIGGER catalog_tracks_update INSTEAD OF UPDATE ON catalog_tracks BEGIN UPDATE recordings SET genre=CASE WHEN NEW.genre IS NOT OLD.genre THEN NEW.genre ELSE genre END,bpm=CASE WHEN NEW.bpm IS NOT OLD.bpm THEN NEW.bpm ELSE bpm END,energy=CASE WHEN NEW.energy IS NOT OLD.energy THEN NEW.energy ELSE energy END,danceability=CASE WHEN NEW.danceability IS NOT OLD.danceability THEN NEW.danceability ELSE danceability END,mb_recording_id=CASE WHEN NEW.mb_recording_id IS NOT OLD.mb_recording_id THEN NEW.mb_recording_id ELSE mb_recording_id END,music_key=CASE WHEN NEW.music_key IS NOT OLD.music_key THEN NEW.music_key ELSE music_key END,music_scale=CASE WHEN NEW.music_scale IS NOT OLD.music_scale THEN NEW.music_scale ELSE music_scale END,mood_happy=CASE WHEN NEW.mood_happy IS NOT OLD.mood_happy THEN NEW.mood_happy ELSE mood_happy END,mood_sad=CASE WHEN NEW.mood_sad IS NOT OLD.mood_sad THEN NEW.mood_sad ELSE mood_sad END,mood_relaxed=CASE WHEN NEW.mood_relaxed IS NOT OLD.mood_relaxed THEN NEW.mood_relaxed ELSE mood_relaxed END,mood_acoustic=CASE WHEN NEW.mood_acoustic IS NOT OLD.mood_acoustic THEN NEW.mood_acoustic ELSE mood_acoustic END,instrumental=CASE WHEN NEW.instrumental IS NOT OLD.instrumental THEN NEW.instrumental ELSE instrumental END,first_enriched_at=CASE WHEN NEW.first_enriched_at IS NOT OLD.first_enriched_at THEN NEW.first_enriched_at ELSE first_enriched_at END,last_enriched_at=CASE WHEN NEW.last_enriched_at IS NOT OLD.last_enriched_at THEN NEW.last_enriched_at ELSE last_enriched_at END,created_at=CASE WHEN NEW.created_at IS NOT OLD.created_at THEN NEW.created_at ELSE created_at END WHERE id=OLD.recording_id; UPDATE youtube_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE video_id=OLD.video_id; UPDATE unresolved_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE entry_id=OLD.id; END;
CREATE TRIGGER discovered_albums_delete INSTEAD OF DELETE ON discovered_albums BEGIN DELETE FROM album_discovery_memberships WHERE album_id=(SELECT album_id FROM album_provider_ids WHERE provider='youtube' AND provider_id=OLD.browse_id); END;
CREATE TRIGGER discovered_albums_update INSTEAD OF UPDATE ON discovered_albums BEGIN UPDATE album_discovery_memberships SET found_at=NEW.found_at,last_shown=NEW.last_shown,first_shown=NEW.first_shown,offered_count=NEW.offered_count,legacy_offered_count=NEW.legacy_offered_count,legacy_first_shown=NEW.legacy_first_shown,legacy_last_shown=NEW.legacy_last_shown WHERE album_id=(SELECT album_id FROM album_provider_ids WHERE provider='youtube' AND provider_id=OLD.browse_id); END;
CREATE TRIGGER discovered_tracks_delete INSTEAD OF DELETE ON discovered_tracks BEGIN DELETE FROM discovery_sources WHERE recording_id=OLD.recording_id; DELETE FROM discovery_memberships WHERE recording_id=OLD.recording_id; END;
CREATE TRIGGER discovered_tracks_update INSTEAD OF UPDATE ON discovered_tracks BEGIN UPDATE catalog_tracks SET genre=NEW.genre,bpm=NEW.bpm,energy=NEW.energy,danceability=NEW.danceability,mb_recording_id=NEW.mb_recording_id,music_key=NEW.music_key,music_scale=NEW.music_scale,mood_happy=NEW.mood_happy,mood_sad=NEW.mood_sad,mood_relaxed=NEW.mood_relaxed,mood_acoustic=NEW.mood_acoustic,instrumental=NEW.instrumental,mb_year=NEW.year,first_enriched_at=COALESCE(first_enriched_at,NEW.last_enriched),last_enriched_at=NEW.last_enriched WHERE id=OLD.id; UPDATE discovery_memberships SET first_shown=NEW.first_shown,last_shown=NEW.last_shown,offered_count=NEW.offered_count WHERE recording_id=OLD.recording_id; END;
CREATE TRIGGER discovery_entry_reassociation BEFORE UPDATE OF recording_id ON catalog_entries WHEN EXISTS(SELECT 1 FROM discovery_memberships d WHERE d.entry_id=OLD.id AND d.recording_id<>NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Replace discovery representative before reassociation'); END;
CREATE TRIGGER discovery_membership_insert BEFORE INSERT ON discovery_memberships WHEN NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Discovery representative belongs to another recording'); END;
CREATE TRIGGER discovery_membership_update BEFORE UPDATE ON discovery_memberships WHEN NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Discovery representative belongs to another recording'); END;
CREATE TRIGGER feedback_subject AFTER INSERT ON rec_feedback BEGIN UPDATE rec_feedback SET recording_id=(SELECT id FROM recordings WHERE identity_key=NEW.item_key),target_type=CASE WHEN EXISTS(SELECT 1 FROM recordings WHERE identity_key=NEW.item_key) THEN 'recording' ELSE target_type END WHERE rowid=NEW.rowid; END;
CREATE TRIGGER history_items_subject AFTER INSERT ON history_items BEGIN UPDATE history_items SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE history_items SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=history_items.recording_id),identity_key) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER play_events_listening_insert AFTER INSERT ON play_events BEGIN
INSERT INTO play_event_sources(event_id,source) VALUES (NEW.id,COALESCE(NULLIF(NEW.source,''),'unknown'));
INSERT INTO play_event_calendar(event_id,day,timezone) VALUES (NEW.id,date(NEW.played_at,'unixepoch'),'UTC');
END;
CREATE TRIGGER play_events_subject AFTER INSERT ON play_events BEGIN UPDATE play_events SET raw_identity_key=NEW.identity_key,recording_id=CASE WHEN NULLIF(trim(NEW.video_id),'') IS NOT NULL THEN (SELECT recording_id FROM youtube_items WHERE video_id=NEW.video_id) ELSE COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) END WHERE rowid=NEW.rowid; UPDATE play_events SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=play_events.recording_id),CASE WHEN NULLIF(trim(NEW.video_id),'') IS NOT NULL AND EXISTS(SELECT 1 FROM recordings WHERE identity_key=NEW.identity_key) THEN '@unresolved-video:'||NEW.video_id ELSE identity_key END) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER playlist_items_position_insert BEFORE INSERT ON playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM unresolved_playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER playlist_items_position_update BEFORE UPDATE ON playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM unresolved_playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER playlist_membership_refs_delete BEFORE DELETE ON playlist_membership_refs WHEN EXISTS(SELECT 1 FROM playlists WHERE id=OLD.id) BEGIN SELECT RAISE(ABORT,'Playlist still references this membership'); END;
CREATE TRIGGER playlist_membership_refs_update BEFORE UPDATE ON playlist_membership_refs WHEN NEW.id IS NOT OLD.id OR NEW.scope_ref IS NOT OLD.scope_ref OR NEW.identity_id IS NOT OLD.identity_id BEGIN SELECT RAISE(ABORT,'Retained playlist membership identity is immutable'); END;
CREATE TRIGGER playlist_tracks_delete INSTEAD OF DELETE ON playlist_tracks BEGIN DELETE FROM playlist_items WHERE playlist_id=OLD.playlist_id AND video_id=(SELECT video_id FROM catalog_entries WHERE id=OLD.track_id); DELETE FROM unresolved_playlist_items WHERE playlist_id=OLD.playlist_id AND entry_id=OLD.track_id; END;
CREATE TRIGGER playlist_tracks_insert INSTEAD OF INSERT ON playlist_tracks BEGIN INSERT INTO playlist_items SELECT NEW.playlist_id,video_id,NEW.position FROM catalog_entries WHERE id=COALESCE((SELECT entry_id FROM legacy_track_refs WHERE legacy_id=NEW.track_id),NEW.track_id) AND video_id IS NOT NULL; INSERT INTO unresolved_playlist_items SELECT NEW.playlist_id,id,NEW.position FROM catalog_entries WHERE id=COALESCE((SELECT entry_id FROM legacy_track_refs WHERE legacy_id=NEW.track_id),NEW.track_id) AND video_id IS NULL; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=COALESCE((SELECT entry_id FROM legacy_track_refs WHERE legacy_id=NEW.track_id),NEW.track_id)) THEN RAISE(ABORT,'Unknown track reference') END; END;
CREATE TRIGGER playlists_membership_insert BEFORE INSERT ON playlists WHEN EXISTS(SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.id AND (m.scope_ref IS NOT NEW.scope_ref OR m.identity_id IS NOT NEW.identity_id)) BEGIN SELECT RAISE(ABORT,'Playlist membership ID already belongs to retained history'); END;
CREATE TRIGGER playlists_membership_record AFTER INSERT ON playlists BEGIN INSERT OR IGNORE INTO playlist_membership_refs(id,scope_ref,identity_id) VALUES (NEW.id,NEW.scope_ref,NEW.identity_id); SELECT CASE WHEN EXISTS(SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.id AND (m.scope_ref IS NOT NEW.scope_ref OR m.identity_id IS NOT NEW.identity_id)) THEN RAISE(ABORT,'Playlist membership ID already belongs to retained history') END; END;
CREATE TRIGGER playlists_membership_update BEFORE UPDATE ON playlists WHEN NEW.id IS NOT OLD.id OR NEW.scope_ref IS NOT OLD.scope_ref OR NEW.identity_id IS NOT OLD.identity_id BEGIN SELECT RAISE(ABORT,'Playlist membership identity is immutable'); END;
CREATE TRIGGER playlists_scope_insert BEFORE INSERT ON playlists WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND s.provider_id=NEW.ytm_playlist_id AND ((s.kind='account' AND s.identity_id=NEW.identity_id AND s.provider_id IN ('LM','SE')) OR (s.kind='shared' AND s.identity_id IS NULL AND s.provider_id NOT IN ('LM','SE')))) BEGIN SELECT RAISE(ABORT,'Playlist scope does not match its account and provider'); END;
CREATE TRIGGER playlists_scope_update BEFORE UPDATE ON playlists WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND s.provider_id=NEW.ytm_playlist_id AND ((s.kind='account' AND s.identity_id=NEW.identity_id AND s.provider_id IN ('LM','SE')) OR (s.kind='shared' AND s.identity_id IS NULL AND s.provider_id NOT IN ('LM','SE')))) BEGIN SELECT RAISE(ABORT,'Playlist scope does not match its account and provider'); END;
CREATE TRIGGER rec_lane_impressions_subject AFTER INSERT ON rec_lane_impressions BEGIN UPDATE rec_lane_impressions SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE rec_lane_impressions SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=rec_lane_impressions.recording_id),identity_key) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER rec_served_impressions_subject AFTER INSERT ON rec_served_impressions BEGIN UPDATE rec_served_impressions SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE rec_served_impressions SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=rec_served_impressions.recording_id),identity_key) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER tracks_update INSTEAD OF UPDATE ON tracks BEGIN UPDATE recordings SET genre=CASE WHEN NEW.genre IS NOT OLD.genre THEN NEW.genre ELSE genre END,bpm=CASE WHEN NEW.bpm IS NOT OLD.bpm THEN NEW.bpm ELSE bpm END,energy=CASE WHEN NEW.energy IS NOT OLD.energy THEN NEW.energy ELSE energy END,danceability=CASE WHEN NEW.danceability IS NOT OLD.danceability THEN NEW.danceability ELSE danceability END,mb_recording_id=CASE WHEN NEW.mb_recording_id IS NOT OLD.mb_recording_id THEN NEW.mb_recording_id ELSE mb_recording_id END,music_key=CASE WHEN NEW.music_key IS NOT OLD.music_key THEN NEW.music_key ELSE music_key END,music_scale=CASE WHEN NEW.music_scale IS NOT OLD.music_scale THEN NEW.music_scale ELSE music_scale END,mood_happy=CASE WHEN NEW.mood_happy IS NOT OLD.mood_happy THEN NEW.mood_happy ELSE mood_happy END,mood_sad=CASE WHEN NEW.mood_sad IS NOT OLD.mood_sad THEN NEW.mood_sad ELSE mood_sad END,mood_relaxed=CASE WHEN NEW.mood_relaxed IS NOT OLD.mood_relaxed THEN NEW.mood_relaxed ELSE mood_relaxed END,mood_acoustic=CASE WHEN NEW.mood_acoustic IS NOT OLD.mood_acoustic THEN NEW.mood_acoustic ELSE mood_acoustic END,instrumental=CASE WHEN NEW.instrumental IS NOT OLD.instrumental THEN NEW.instrumental ELSE instrumental END,first_enriched_at=CASE WHEN NEW.first_enriched_at IS NOT OLD.first_enriched_at THEN NEW.first_enriched_at ELSE first_enriched_at END,last_enriched_at=CASE WHEN NEW.last_enriched_at IS NOT OLD.last_enriched_at THEN NEW.last_enriched_at ELSE last_enriched_at END,created_at=CASE WHEN NEW.created_at IS NOT OLD.created_at THEN NEW.created_at ELSE created_at END WHERE id=OLD.recording_id; UPDATE youtube_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE video_id=OLD.video_id; UPDATE unresolved_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE entry_id=OLD.id; END;
CREATE TRIGGER unresolved_playlist_items_position_insert BEFORE INSERT ON unresolved_playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER unresolved_playlist_items_position_update BEFORE UPDATE ON unresolved_playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
